const projectArt=p=>`<div class="projectArt art-${e(p.accent)}" aria-label="Original conceptual diagram for ${e(p.title)}; not a product screenshot" role="img"><span class="artCross artCrossOne" aria-hidden="true">+</span>${projectDiagrams[p.number] || ''}<span class="artBottom">CONCEPTUAL SYSTEM MAP · ${e(p.number)}</span><span class="artTop">${e(p.category)}</span></div>`
const stageForProject=p=>p.status.toLowerCase().includes('deployed')?'Deployed application':p.status.toLowerCase().includes('research')?'Research prototype':p.status.toLowerCase().includes('development')?'In development':p.status.toLowerCase().includes('live website')?'Live website / initiative':p.status.toLowerCase().includes('prototype')?p.status:p.status
const projectCard=p=>`<article class="projectCard" data-project="${e(p.number)}" data-filters="${e(p.filters.join(' '))}"><div class="projectVisual">${p.evidenceImage?`<div class="verifiedImage"><img loading="lazy" decoding="async" src="${safeURL(p.evidenceImage)}" alt="${e(p.evidenceImageCaption)}"/><span class="evidenceMediaCaption">${e(p.evidenceImageCaption)}   <a href="#field-proof">View gallery ↗</a></span></div>`:projectArt(p)}<span class="projectBigNumber" aria-hidden="true">${e(p.number)}</span></div><div class="projectContent"><div class="projectMeta"><span>PROJECT / ${e(p.number)}</span><span class="projectStatus" title="${e(p.status)}">${e(stageForProject(p))}</span></div><h3>${e(p.title)}</h3><p class="projectDescription">${e(p.description)}</p><div class="projectFoot"><div class="projectTags">${p.stack.map(t=>`<span>${e(t)}</span>`).join('')}</div></div>${p.caseStudy ? `<details class="caseStudy"><summary>Implementation & limitations <span aria-hidden="true">↗</span></summary><div class="caseStudyBody"><div><strong>Challenge</strong><p>${e(p.caseStudy.problem)}</p></div><div><strong>Approach</strong><p>${e(p.caseStudy.approach)}</p></div><div><strong>Evidence</strong><p>${e(p.caseStudy.verification)}</p></div><div class="caseStudyCaveat"><strong>Scope / limitations</strong><p>${e(p.caseStudy.caveat)}</p></div></div></details>`:''}<div class="projectLinks">${p.links.length?p.links.filter(l=>safeURL(l.url)).map(l=>`<a href="${safeURL(l.url)}" target="_blank" rel="noopener noreferrer" aria-label="${e(l.label)} — ${e(p.title)}">${e(l.label)} ${icon('arrow',15)}</a>`).join(''):'<span>No public demo link provided</span>'}</div></div></article>`

