const artifactExplorerMarkup=()=>`<div class="atlas" id="evidenceAtlas"><div class="atlasHead"><div><span class="atlasKicker">EVIDENCE DESK / 4 INVESTIGATIONS</span><h3>Select the engineering record.</h3></div><span class="atlasHeadMeta">SOURCE CODE · TESTS · LIMITS</span></div><div class="atlasTabs" role="tablist" aria-label="Select engineering case">${artifactAtlas.map((a,i)=>`<button type="button" role="tab" class="atlasTab${i===0?' isActive':''}" id="atlasTab-${a.id}" aria-controls="atlasPanel-${a.id}" aria-selected="${i===0}" tabindex="${i===0?'0':'-1'}" data-atlas-tab="${a.id}"><span>${a.index} / ${e(a.type)}</span><strong>${e(a.title)}</strong></button>`).join('')}</div><div class="atlasPanels">${artifactAtlas.map((a,i)=>`<section id="atlasPanel-${a.id}" class="atlasPanel" role="tabpanel" aria-labelledby="atlasTab-${a.id}" data-atlas-panel="${a.id}" ${i!==0?'hidden':''}><div class="atlasStory"><span class="atlasCaseId">CASE ${a.index} / ${e(a.role.toUpperCase())}</span><h4>${e(a.headline)}</h4><div class="atlasQuestion"><small>THE PROBLEM</small><p>${e(a.question)}</p></div><div class="atlasDecision"><small>ENGINEERING DECISION</small><p>${e(a.decision)}</p></div><div class="atlasLimit"><small>WHAT THE RECORD ACTUALLY PROVES</small><p>${e(a.reality)}</p></div><details class="atlasCaveat"><summary>Scope and known limitations <span aria-hidden="true">+</span></summary><p>${e(a.limit)}</p></details></div><div class="atlasArtifacts"><div class="atlasArtifactTop"><span><i aria-hidden="true"></i> VERIFIED REPOSITORY LOCATIONS</span><span>CLICK TO INSPECT ↗</span></div>${a.screenshot?`<div class="atlasScreenshot"><img loading="lazy" src="${safeURL(a.screenshot)}" alt="${e(a.screenshotAlt || a.title + ' captured interface')}"/><span>${e(a.screenshotLabel || 'STATIC PROJECT SCREENSHOT / NOT A CONCEPT RENDER')}</span></div>`:`<div class="atlasCodeVisual" aria-hidden="true"><span class="atlasCodeBars"><i></i><i></i><i></i></span><strong>${e(a.title.toUpperCase())} / SOURCE TREE</strong><span>EXPLORE THE ARTIFACTS BELOW</span><div class="atlasCodePath"><span>src / docs / tests</span><span>↗</span></div></div>`}<div class="atlasFiles">${a.files.map(([path,note,url],idx)=>`<a href="${safeURL(url)}" target="_blank" rel="noopener noreferrer" class="atlasFile"><span class="atlasFileNum">${String(idx+1).padStart(2,'0')}</span><span class="atlasFileBody"><strong>${e(path)}</strong><small>${e(note)}</small></span><span class="atlasFileArrow" aria-hidden="true">↗</span></a>`).join('')}</div><a class="atlasPrimary" href="${safeURL(a.cta[1])}" target="_blank" rel="noopener noreferrer">${e(a.cta[0])} <span aria-hidden="true">↗</span></a></div></section>`).join('')}</div><p class="atlasStatus srOnly" id="atlasStatus" role="status" aria-live="polite">Our Hidden Universe engineering record selected.</p></div>`
// A single source-grounded detail block lives inside each canonical case note.
