const caseDossierMarkup = (id) => {
 const item = caseDossiers[id]
 if (!item) return ''
 const line = (title, value) => `<div class="dossierField"><h5>${e(title)}</h5><p>${e(value)}</p></div>`
 return `<section class="dossier" aria-label="${e(id)} source-backed technical analysis">
  <div class="dossierTop"><span>ENGINEERING RECORD / IMPLEMENTATION & TEST CONTRACT</span><span>INSPECTABLE SOURCE · NOT A PERFORMANCE CERTIFICATE</span></div>
  <div class="dossierGrid">
   ${line('Constraint / failure mode',item.problem)}
   ${line('Design choice',item.decision)}
   ${line('Trade-off',item.tradeoff)}
   ${line('How to inspect the test',item.reproducible)}
   ${line('Expected result / scope',item.expected)}
   ${line('Verified project stage',item.state)}
  </div>
  <div class="dossierSources"><h5>Open the exact supporting files</h5>
   <div>${item.evidence.map(([label,url])=>`<a href="${safeURL(url)}" target="_blank" rel="noopener noreferrer">${e(label)} <span aria-hidden="true">↗</span></a>`).join('')}</div>
  </div>
 </section>`
}
const caseFilesMarkup=()=>`<section class="caseFiles section wrap" id="case-files" aria-labelledby="caseFilesTitle"><div class="caseFilesHeader"><div class="smallCaps">ENGINEERING EVIDENCE / REAL SOURCE ARTIFACTS</div><h2 id="caseFilesTitle">Architecture, tests, and trade-offs.</h2><p>Four technical records: implementation decisions, source files, testing evidence, and known limitations.</p></div><nav class="v14CaseQuickNav" aria-label="Open a project case study"><a href="#case-ohs">Our Hidden Universe <span>Product / Firebase ↗</span></a><a href="#case-news">NewsSources <span>Data ingestion / PostgreSQL ↗</span></a><a href="#case-mulyankan">Mulyankan <span>Evidence / human review ↗</span></a><a href="#case-earthbridge">EarthBridge <span>Retrieval / evaluation ↗</span></a></nav><details class="atlasDrawer"><summary>Compare source files across all four projects <span aria-hidden="true">↘</span></summary>${artifactExplorerMarkup()}</details><div class="caseNotesHead"><div><strong>Deep-dive notes</strong><span>Engineering problem · architecture · verification · caveats</span></div><button type="button" id="caseNotesToggle" aria-expanded="false" aria-controls="caseFilesGrid">Expand all case notes <span aria-hidden="true">↘</span></button></div><div class="caseFilesGrid" id="caseFilesGrid" hidden>${caseFileData.map(c=>`<article class="caseFile" data-case-role="${c.role}" id="case-${c.id}"><div class="caseFileTop"><span>${c.label}</span><strong>CODE-BACKED CASE / ${c.id.toUpperCase()}</strong></div>${c.screenshot?`<div class="caseSourceCapture"><img loading="lazy" src="${safeURL(c.screenshot)}" alt="${e(c.screenshotAlt || c.title + ' captured interface')}"/><span>${e(c.screenshotLabel || 'Actual project screenshot / static capture')}</span></div>`:''}<h3>${c.title}</h3><p class="caseFileHeadline">${c.headline}</p><div class="caseFlow" aria-label="Simplified architectural stages">${c.steps.map((v,i)=>`<span><b>${String(i+1).padStart(2,'0')}</b>${v}</span>`).join('')}</div><details class="caseFileDetails"><summary>Read engineering case study <span aria-hidden="true">↗</span></summary><div class="caseFacts"><div><h4>Engineering problem</h4><p>${c.problem}</p></div><div><h4>Approach</h4><p>${c.approach}</p></div><div><h4>Verification</h4><p>${c.verification}</p></div><div><h4>Honest limits</h4><p>${c.limits}</p></div></div>${caseDossierMarkup(c.id)}</details></article>`).join('')}</div></section>`

