document.getElementById('root').innerHTML=appMarkup()
// A compact, accessible index: filters are optional and never hide the project links permanently.
const filterButtons=[...document.querySelectorAll('.projectFilter')]
const projectCards=[...document.querySelectorAll('.projectCard')]
filterButtons.forEach(button=>button.addEventListener('click',()=>{
  const filter=button.dataset.filter
  let count=0
  filterButtons.forEach(item=>{
    const active=item===button
    item.classList.toggle('isActive',active)
    item.setAttribute('aria-pressed',String(active))
  })
  projectCards.forEach(card=>{
    const visible=filter==='all'||card.dataset.filters.split(' ').includes(filter)
    card.hidden=!visible
    if(visible)count++
  })
  document.getElementById('filterCount').textContent=`${count} project${count===1?'':'s'} shown`
}))

const menu=document.getElementById('menuToggle')
const nav=document.getElementById('main-nav')
function closeMenu(){nav.classList.remove('navOpen');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.innerHTML=icon('menu',23)}
menu.addEventListener('click',()=>{const isOpen=nav.classList.toggle('navOpen');menu.setAttribute('aria-expanded',String(isOpen));menu.setAttribute('aria-label',isOpen?'Close navigation':'Open navigation');menu.innerHTML=icon(isOpen?'x':'menu',23)})
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu))
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&nav.classList.contains('navOpen')){closeMenu();menu.focus()}})

// Keep optional-project discovery working for mouse, keyboard, and touch.
const archiveFilterButtons=[...document.querySelectorAll('[data-archive-filter]')]
const archiveCards=[...document.querySelectorAll('.archiveCard')]
function filterArchive(role='all'){
 if(!['all','fullstack','software','ml'].includes(role))return
 let shown=0
 archiveFilterButtons.forEach(button=>{const on=button.dataset.archiveFilter===role;button.classList.toggle('isActive',on);button.setAttribute('aria-pressed',String(on))})
 archiveCards.forEach(card=>{const match=role==='all'||card.dataset.archiveLenses.split(' ').includes(role);card.hidden=!match;if(match)shown++})
 const live=document.getElementById('archiveCount')
 if(live)live.textContent=`${shown} additional project${shown===1?'':'s'} shown`
}
archiveFilterButtons.forEach(button=>button.addEventListener('click',()=>filterArchive(button.dataset.archiveFilter)))
filterArchive()

// The workbench state is tab-local, fully interactive, and does not use an external API.
setupEvidenceWorkbench()
setupPortfolioExperience({ projects, orbitNotes })
setupCareerModes()
setupV8Interactions()
setupSceneV9()
// Recruiter discovery: grid fallback and mode-specific case-file priority.
setupV10Experience()
setupV11Experience()
setupEvidenceGallery()
// Pause decorative, perpetual motion when its lab/workspace is offscreen.
// Real controls, timers, data and interaction state are intentionally untouched.
if ('IntersectionObserver' in window && !matchMedia('(prefers-reduced-motion: reduce)').matches) {
  const ambientTargets=document.querySelectorAll('.schematic,.orbitStage,.researchStage,.systemsFlowGraphic,.projectVisual')
  const motionObserver=new IntersectionObserver(entries=>{
    for(const entry of entries) entry.target.classList.toggle('ambientPaused',!entry.isIntersecting)
  },{rootMargin:'120px 0px'})
  ambientTargets.forEach(node=>{node.classList.add('ambientPaused');motionObserver.observe(node)})
}
// Do not cover the workbench with the discovery nudge while it is being used.
if ('IntersectionObserver' in window) {
  const lab = document.getElementById('lab')
  const hintObserver = new IntersectionObserver(entries => {
    document.body.classList.toggle('isAtWorkbench', entries[0].isIntersecting)
  }, { threshold: 0.08 })
  hintObserver.observe(lab)
}
document.addEventListener('keydown',ev=>{
 if(ev.defaultPrevented||ev.repeat||ev.ctrlKey||ev.metaKey||ev.altKey||ev.key.toLowerCase()!=='l')return
 if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||document.activeElement?.isContentEditable)return
 document.getElementById('lab').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})
})
